using System.Text.Json;
using Metarill.Core.Metadata;
using Xunit;
namespace Metarill.Generation.Tests;

/// <summary>原全局单值／多值、R0中间节点及R1下游在同一完整发布模型中形成事务依赖。</summary>
[Collection(StandaloneProcessBudgetCollection.Name)]
public sealed class GlobalCacheFreshCatalogTests
{
    /// <summary>所有原页面与实体由元数据生成，实际包内Foundation编译，不手写标准CRUD。</summary>
    [Theory][InlineData("cross3")][InlineData("cross5")][InlineData("cross6")][InlineData("cross7")]
    public async Task Cached_global_relations_compile_full_package_and_keep_original_controls(string profile)
    {
        var c=Catalog(profile);var before=JsonSerializer.Serialize(c);var boundary=Path.Combine(Path.GetTempPath(),"metarill-global-cache-catalog");var directory=Path.Combine(boundary,Guid.NewGuid().ToString("N"));try{var model=GenerationModel.Create(c,"Example.GlobalCacheFresh");Assert.Empty(GenerationCapabilityAudit.Collect(model));var output=Path.Combine(directory,"application");Assert.True(new ApplicationPackager().Create(c,output,model.Namespace,NonRedundantApplicationFixture.Root()).FrontendIncluded);foreach(var operation in new[]{"restore","build"})await NonRedundantApplicationFixture.BuildAsync(output,operation);var probe=NonRedundantApplicationFixture.Start("node",output);foreach(var argument in new[]{Path.Combine(NonRedundantApplicationFixture.TestDirectory(),"GlobalMultipleVueProbe.mjs"),output})probe.ArgumentList.Add(argument);await NonRedundantApplicationFixture.RunAsync(probe);var target=File.ReadAllText(Path.Combine(output,"backend/generated/Services/GsSingleSharedService.g.cs"));Assert.Contains("entity.Id,actor.ProjectId,new HashSet",target);var source=File.ReadAllText(Path.Combine(output,"backend/generated/Services/GsSingleSourceService.g.cs"));Assert.DoesNotContain("entity.GlobalName = source.GlobalName",source);Assert.DoesNotContain("entity.NestedLabel = source.NestedLabel",source);Assert.Contains("entity.GlobalId = source.GlobalId",source);Assert.Equal(before,JsonSerializer.Serialize(c));}finally{if(Directory.Exists(directory))await TestDirectoryCleanup.DeleteAsync(directory,boundary);}
    }
    /// <summary>只有全局下拉、不含文件／导出／多选的来源也必须注入真实授权器。</summary>
    [Theory][InlineData(false)][InlineData(true)]public async Task Plain_global_list_keeps_authorization_dependency_without_other_features(bool derived)
    {
        var c=Catalog("cross3");var source=c.ConfigPages.Single(x=>x.Id=="201");source.IsImport=source.IsExport=source.IsCopy=0;var keep=(derived?new[]{"nested_id","nested_label"}:new[]{"global_id","global_name","global_score"}).Concat(new[]{"id","name","yz_project_id","delete_no","parent_id","segment"}).ToArray();c.ConfigTables.RemoveAll(x=>x.Id=="7");c.ConfigColumns.RemoveAll(x=>x.ConfigTableId=="7");c.ConfigPages.RemoveAll(x=>x.Id=="701");c.ConfigPageColumns.RemoveAll(x=>x.ConfigPageId=="701");c.ConfigMenus.RemoveAll(x=>x.ConfigPageId=="701");var removed=c.ConfigColumns.Where(x=>x.ConfigTableId=="2"&&!keep.Contains(x.ColumnName)).Select(x=>x.Id).ToHashSet(StringComparer.Ordinal);c.ConfigColumns.RemoveAll(x=>removed.Contains(x.Id));c.ConfigPageColumns.RemoveAll(x=>removed.Contains(x.ConfigColumnId));var boundary=Path.Combine(Path.GetTempPath(),"metarill-global-cache-minimal");var directory=Path.Combine(boundary,Guid.NewGuid().ToString("N"));try{new CSharpGenerator().Generate(c,Path.Combine(directory,"generated"),"Example.GlobalCacheMinimal");var service=File.ReadAllText(Path.Combine(directory,"generated/Services/GsSingleSourceService.g.cs"));Assert.Contains("IRuntimeAuthorization",service);Assert.Contains(derived?"DerivedOptionsScope201_2308Async":"OptionsScope201_2301Async",service);await GeneratedRelationOptionsMySqlTests.BuildGenerated(directory);}finally{if(Directory.Exists(directory))await TestDirectoryCleanup.DeleteAsync(directory,boundary);}
    }
    /// <summary>系统项目字段仍只承担真实上下文，不能被隐藏普通关系发现逻辑额外接为候选。</summary>
    [Theory][InlineData("SelectPage",false)][InlineData("List",true)]public async Task System_project_context_keeps_original_special_boundary(string control,bool originalList)
    {
        var c=Catalog("cross3");var column=c.ConfigColumns.Single(x=>x.ConfigTableId=="2"&&x.ColumnName=="yz_project_id");column.ControlKind=control;if(originalList)c.ConfigPageColumns.Add(new(){Id="20199"+column.Id,YzProjectId=c.YzProjectId,ConfigPageId="201",ConfigColumnId=column.Id,IsShow=1,IsEdit=1});column.LinkConfigTableId="3";column.Extra["linkConfigPageId"]=JsonSerializer.SerializeToElement("303");column.ControlDetail="{\"tableId\":\"3\",\"pageId\":\"303\",\"nameField\":\"name\"}";var boundary=Path.Combine(Path.GetTempPath(),"metarill-global-system-context");var directory=Path.Combine(boundary,Guid.NewGuid().ToString("N"));try{new CSharpGenerator().Generate(c,Path.Combine(directory,"generated"),"Example.GlobalSystemContext");var source=File.ReadAllText(Path.Combine(directory,"generated/Services/GsSingleSourceService.g.cs"));if(originalList)Assert.Contains("OptionsScope201_"+column.Id+"Async",source);else Assert.DoesNotContain("OptionsScope201_"+column.Id+"Async",source);Assert.Contains("OptionsScope201_2301Async",source);await GeneratedRelationOptionsMySqlTests.BuildGenerated(directory);}finally{if(Directory.Exists(directory))await TestDirectoryCleanup.DeleteAsync(directory,boundary);}
    }
    /// <summary>原四个模型的名称投影与目标项目列／来源父交叉保持。</summary>
    internal static MetadataCatalog Catalog(string profile)
    {
        var c=GlobalMultipleFreshCatalogTests.Catalog(profile);if(profile=="cross6")c.ConfigColumns.RemoveAll(x=>x.ConfigTableId=="3"&&x.ColumnName=="delete_no");c.YzProjectName="全局缓存正式验收";c.ConfigPageColumns.Single(x=>x.ConfigPageId=="301"&&x.ConfigColumnId==c.ConfigColumns.Single(y=>y.ConfigTableId=="3"&&y.ColumnName=="score").Id).IsEdit=1;c.ConfigTables.Single(x=>x.Id=="2").IsRongyu=1;var parent=GlobalMultipleFreshCatalogTests.Definition(profile).Parent;var type=GlobalSingleFreshCatalogTests.Definition(profile).Type;
        var single=JsonSerializer.Deserialize<PageMetadata>(JsonSerializer.Serialize(c.ConfigPages.Single(x=>x.Id=="302")))!;single.Id="303";single.Extra["type"]=JsonSerializer.SerializeToElement(1);c.ConfigPages.Add(single);foreach(var field in c.ConfigPageColumns.Where(x=>x.ConfigPageId=="302").ToArray()){var copy=JsonSerializer.Deserialize<PageColumnMetadata>(JsonSerializer.Serialize(field))!;copy.Id="303"+field.Id;copy.ConfigPageId="303";c.ConfigPageColumns.Add(copy);}Menu("303");
        Add("2301","2","global_id","全局下拉",type,"List","3","301","name","segment=@formParameters.segment");Cache("2302","2","global_name","全局名称","string","global.name");Cache("2303","2","global_score","全局分值","decimal","global.score");Add("2304","2","selected_id","全局单选","int64","SelectPage","3","303","name","");Cache("2305","2","selected_name","单选名称","string","selected.name");Add("2306","2","hidden_id","隐藏单值","int64","List","3","301","name","");c.ConfigColumns.Single(x=>x.Id=="2306").DefaultValue="9007199254745001";c.ConfigPageColumns.RemoveAll(x=>x.ConfigColumnId=="2306");Cache("2307","2","hidden_name","隐藏名称","string","hidden.name",false);
        c.ConfigTables.Add(new(){Id="6",YzProjectId=c.YzProjectId,TableName="gs_cache_middle",IsRongyu=0});Basics("6");Add("6104","6","shared_id","共享目标","int64","List","3","301","name","");Cache("6105","6","label","派生名称","string","shared.name");Page("6","601");Add("2308","2","nested_id","中间节点","int64","List","6","601","label","");Cache("2309","2","nested_label","中间名称","string","nested.label");
        c.ConfigTables.Add(new(){Id="7",YzProjectId=c.YzProjectId,TableName="gs_cache_tail",IsRongyu=1});Basics("7");Add("7104","7","source_id","来源记录","int64","List","2","201","global_name","");Cache("7105","7","source_global_name","下游名称","string","source.global_name");if(parent){Add("7106","7","parent_id","来源父","int64","","5","","","");c.ConfigPageColumns.RemoveAll(x=>x.ConfigColumnId=="7106");}Page("7","701");if(parent)c.ConfigPages.Single(x=>x.Id=="701").WhereSql+=" AND parent_id=@parent_id";return c;
        /// <summary>物理身份与删除列在每个普通节点显式声明。</summary>
        void Basics(string table){Add(table+"101",table,"id","ID","int64",key:true);Add(table+"102",table,"yz_project_id","项目","int64");Add(table+"103",table,"delete_no","删除标记","datetime");}
        /// <summary>仅增加验收元数据，来源字段、DTO、Mapper及页面仍正规生成。</summary>
        void Add(string id,string table,string field,string label,string logical,string control="",string target="",string page="",string name="",string where="",bool key=false){var col=new ColumnMetadata{Id=id,YzProjectId=c.YzProjectId,ConfigTableId=table,ColumnName=field,Name=label,LogicalType=logical,ColumnLength=logical=="string"?"max":"",IsDbNotNull=key?1:0,ControlKind=control,LinkConfigTableId=target};if(control.Length>0){col.ControlDetail=JsonSerializer.Serialize(new{tableId=target,table=c.ConfigTables.Single(x=>x.Id==target).TableName,pageId=page,nameField=name,whereSql=where});if(page.Length>0)col.Extra["linkConfigPageId"]=JsonSerializer.SerializeToElement(page);}c.ConfigColumns.Add(col);if(table=="2")Field("201",col,!key);}
        /// <summary>物理R1缓存与R0派生字符串使用同一明确路径；隐藏列不进入VO。</summary>
        void Cache(string id,string table,string field,string label,string logical,string path,bool shown=true){Add(id,table,field,label,logical);var col=c.ConfigColumns.Single(x=>x.Id==id);col.Extra["isJoinColumn"]=JsonSerializer.SerializeToElement(1);col.Extra["columnFullName"]=JsonSerializer.SerializeToElement(path);c.ConfigPageColumns.RemoveAll(x=>x.ConfigColumnId==id);if(shown&&table=="2")Field("201",col,false);}
        /// <summary>页面只声明原可读／可写开关，缓存列不可编辑。</summary>
        void Field(string page,ColumnMetadata col,bool edit)=>c.ConfigPageColumns.Add(new(){Id=page+col.Id,YzProjectId=c.YzProjectId,ConfigPageId=page,ConfigColumnId=col.Id,IsShow=1,IsEdit=edit?1:0});
        /// <summary>普通中间与下游仍以真实项目过滤。</summary>
        void Page(string table,string id){c.ConfigPages.Add(new(){Id=id,ConfigTableId=table,YzProjectId=c.YzProjectId,YzAdminTypeId="5",WhereSql="yz_project_id=@current_yz_project_id"});foreach(var col in c.ConfigColumns.Where(x=>x.ConfigTableId==table&&!new[]{"id","yz_project_id","delete_no","parent_id"}.Contains(x.ColumnName)))Field(id,col,!col.Extra.ContainsKey("isJoinColumn"));Menu(id);}
        /// <summary>完整包菜单继续使用原生成页入口。</summary>
        void Menu(string page)=>c.ConfigMenus.Add(new(){Id="800"+page,YzProjectId=c.YzProjectId,YzAdminTypeId="5",Name="全局缓存"+page,Kind="GENERATED_PAGE",ConfigPageId=page});
    }
}
